svg.script:
const F={F:["11111","10000","10000","11110","10000","10000","10000"],A:["01110","10001","10001","11111","10001","10001","10001"],B:["11110","10001","10001","11110","10001","10001","11110"],I:["11111","00100","00100","00100","00100","00100","11111"],O:["01110","10001","10001","10001","10001","10001","01110"]};
const R=["#99f6e4","#5eead4","#2dd4bf","#14b8a6","#0d9488","#0f766e"];const t=14;let x=40;
for(const ch of "FABIO"){const g=F[ch];for(let r=0;r<7;r++)for(let c=0;c<5;c++){if(g[r][c]==="1"){const d=document.createElementNS("http://www.w3.org/2000/svg","rect");d.setAttribute("x",x+c*t);d.setAttribute("y",70+r*t);d.setAttribute("width",t);d.setAttribute("height",t);d.setAttribute("fill",R[(r+c+x/t)%6|0]);document.getElementById("fw").appendChild(d);}}x+=6*t;}
const caret=document.createElementNS("http://www.w3.org/2000/svg","rect");caret.setAttribute("x",x+4);caret.setAttribute("y",70+6*t);caret.setAttribute("width",t);caret.setAttribute("height",t);caret.setAttribute("fill","#0d9488");document.getElementById("fw").appendChild(caret);
